CREATE TABLE api_keys (id UUID PRIMARY KEY, key_hash VARCHAR(64) UNIQUE NOT NULL, name VARCHAR(100) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, last_used_at TIMESTAMPTZ);
CREATE TABLE gyms (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL, address VARCHAR(255) NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE members (id UUID PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(160) UNIQUE NOT NULL, phone VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE membership_plans (id UUID PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, plan_type VARCHAR(30) NOT NULL, duration_days INTEGER NOT NULL CHECK (duration_days > 0), price NUMERIC(12,2) NOT NULL CHECK (price >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE memberships (id UUID PRIMARY KEY, member_id UUID NOT NULL REFERENCES members(id), plan_id UUID NOT NULL REFERENCES membership_plans(id), status VARCHAR(30) NOT NULL, start_date DATE, end_date DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(member_id, plan_id, status));
CREATE TABLE gym_records (id UUID PRIMARY KEY, record_type VARCHAR(40) NOT NULL, title VARCHAR(160) NOT NULL, member_id UUID REFERENCES members(id), status VARCHAR(30) NOT NULL, scheduled_at TIMESTAMPTZ, amount NUMERIC(12,2), details VARCHAR(1000), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_gym_records_type ON gym_records(record_type);
CREATE INDEX idx_memberships_member ON memberships(member_id);
